import {announce} from '@github-ui/aria-live'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {type FieldVisibilityPermissions, type KnownType, KnownTypes} from '@github-ui/issue-fields-shared/issue-field'
import type {IssueType} from '@github-ui/issue-types/types/issue-type'
import {Link} from '@github-ui/react-core/link'
import {VALIDATION_MESSAGES} from '@github-ui/shared-single-select-components/resources'
import type {SingleSelectOptionWithId} from '@github-ui/shared-single-select-components/types'
import {useNavigate} from '@github-ui/use-navigate'
import {Banner, SkeletonBox} from '@primer/react'
import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {Resources} from '../constants/strings'
import {areOptionsEqual} from '../helpers/options-comparison'
import {useInputFieldsErrors} from '../hooks/use-input-fields-errors'
import styles from '../routes/NewPage.module.css'
import {IssueFieldActions} from './IssueFieldActions'
import {IssueFieldDataType} from './IssueFieldDataType'
import {IssueFieldDescription} from './IssueFieldDescription'
import {IssueFieldName} from './IssueFieldName'
import {IssueFieldNotPinnedConfirmationDialog} from './IssueFieldNotPinnedConfirmationDialog'
import {IssueFieldPinToIssueTypesDialog} from './IssueFieldPinToIssueTypesDialog'
import {IssueFieldsPinToIssueTypes} from './IssueFieldsPinToIssueTypes'
import {IssueFieldVisibilityPermissions} from './IssueFieldVisibilityPermissions'
import {LazyIssueFieldOptions as IssueFieldOptions} from './lazy-issue-field-options'
import {Title} from './Title'

export interface IssueFieldFormData {
  name: string
  description: string
  type: KnownType
  options?: SingleSelectOptionWithId[]
  visibility?: FieldVisibilityPermissions
}

export interface IssueFieldInitialData {
  name?: string
  description?: string
  type?: KnownType
  options?: SingleSelectOptionWithId[]
  id?: string
  organization?: string
}

const defaultInitialData = {}

interface IssueFieldFormContainerProps {
  initialData?: IssueFieldInitialData
  organizationLogin: string
  pageTitle: string
  fieldNames: string[]
  confirmLabel: string
  cancelLabel?: string
  typeDisabled?: boolean
  onSubmit: (data: IssueFieldFormData) => Promise<void>
  error?: string | null
  successMessage?: boolean
  onFormChange?: () => void
  isCreateNew?: boolean
  allIssueTypes?: IssueType[]
  pinnedIssueTypes?: IssueType[]
  pinnedToNoTypeIssues?: boolean
  initialPinnedIssueTypeIds?: string[]
  initialPinnedToNoTypeIssues?: boolean
  onPinToIssueTypesChange?: (selectedIssueTypeIds: string[], pinnedToNoTypeIssues: boolean) => void
  onVisibilityPermissionsChange?: (visibility: FieldVisibilityPermissions) => void
  fieldVisibilityPermissions?: FieldVisibilityPermissions
}

export function IssueFieldForm({
  initialData = defaultInitialData,
  organizationLogin,
  pageTitle,
  fieldNames,
  confirmLabel,
  cancelLabel,
  isCreateNew,
  onSubmit,
  typeDisabled,
  error,
  successMessage,
  onFormChange,
  allIssueTypes,
  pinnedIssueTypes,
  pinnedToNoTypeIssues = false,
  initialPinnedIssueTypeIds,
  initialPinnedToNoTypeIssues,
  onPinToIssueTypesChange,
  onVisibilityPermissionsChange,
  fieldVisibilityPermissions = 'org_only',
}: IssueFieldFormContainerProps) {
  const isPinToIssueTypesEnabled = allIssueTypes && pinnedIssueTypes
  const multiSelectEnabled = isFeatureEnabled('issue_fields_multi_select')
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false)
  const [hasStartedEditing, setHasStartedEditing] = useState<boolean>(false)
  const [isPinToIssueTypesDialogOpen, setIsPinToIssueTypesDialogOpen] = useState<boolean>(false)
  const [isNotPinnedConfirmationDialogOpen, setIsNotPinnedConfirmationDialogOpen] = useState<boolean>(false)
  const editPinToIssueTypesButtonRef = useRef<HTMLButtonElement>(null)

  const [name, setName] = useState<string>(initialData.name || '')
  const [description, setDescription] = useState<string>(initialData.description || '')
  const [type, setType] = useState<KnownType>(initialData.type || KnownTypes['text'])
  const [options, setOptions] = useState<SingleSelectOptionWithId[]>(initialData.options || [])

  const [initialName, setInitialName] = useState<string>(initialData.name || '')
  const [initialDescription, setInitialDescription] = useState<string>(initialData.description || '')
  const [initialOptions, setInitialOptions] = useState<SingleSelectOptionWithId[]>(initialData.options || [])
  const [initialFieldVisibilityPermissions, setInitialFieldVisibilityPermissions] =
    useState<FieldVisibilityPermissions>(fieldVisibilityPermissions)

  // Track initial pinned issue types values to detect changes (updated on successful save)
  const [initialPinnedIds, setInitialPinnedIds] = useState<string[]>(initialPinnedIssueTypeIds ?? [])
  const [initialPinnedToNoType, setInitialPinnedToNoType] = useState<boolean>(initialPinnedToNoTypeIssues ?? false)

  // Update form state when initialData changes (e.g., after successful save with new option IDs)
  useEffect(() => {
    if (initialData.options !== options) {
      let update = false
      const newOptions =
        options.map(option => {
          const initialOption = initialData.options?.find(o => o.name === option.name)
          if (initialOption && initialOption.id !== option.id) {
            // after server updates, we need to replace temporary ID with real ID
            update = true
          }
          return initialOption ? {...option, id: initialOption.id} : option
        }) || []

      // eslint-disable-next-line react-hooks/set-state-in-effect
      if (update) setOptions(newOptions)
    }
  }, [initialData, initialData.options, options])

  const formHasChanged = useMemo(() => {
    if (isCreateNew) return false

    const nameChanged = name !== initialName
    const descriptionChanged = description !== initialDescription
    const optionsChanged = !areOptionsEqual(options, initialOptions)

    const currentPinnedIds = [...(pinnedIssueTypes?.map(t => t.id) ?? [])].sort().join(',')
    const initialPinnedIdsStr = [...initialPinnedIds].sort().join(',')
    const pinToIssuesChanged =
      currentPinnedIds !== initialPinnedIdsStr || pinnedToNoTypeIssues !== initialPinnedToNoType
    const fieldVisibilityPermissionsChanged = fieldVisibilityPermissions !== initialFieldVisibilityPermissions

    return (
      nameChanged || descriptionChanged || optionsChanged || pinToIssuesChanged || fieldVisibilityPermissionsChanged
    )
  }, [
    isCreateNew,
    name,
    initialName,
    description,
    initialDescription,
    options,
    initialOptions,
    pinnedIssueTypes,
    initialPinnedIds,
    pinnedToNoTypeIssues,
    initialPinnedToNoType,
    initialFieldVisibilityPermissions,
    fieldVisibilityPermissions,
  ])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setHasStartedEditing(formHasChanged)
  }, [formHasChanged])

  useEffect(() => {
    if (successMessage) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setHasStartedEditing(false)
      setInitialName(name)
      setInitialDescription(description)
      setInitialOptions([...options])
      setInitialPinnedIds(pinnedIssueTypes?.map(t => t.id) ?? [])
      setInitialPinnedToNoType(pinnedToNoTypeIssues)
      setInitialFieldVisibilityPermissions(fieldVisibilityPermissions)
    }
  }, [successMessage, name, description, options, pinnedIssueTypes, pinnedToNoTypeIssues, fieldVisibilityPermissions])

  const navigate = useNavigate()

  const {
    fieldNameRef,
    fieldDescriptionRef,
    nameError,
    setNameError,
    descriptionError,
    setDescriptionError,
    setShouldFocusError,
    validate,
  } = useInputFieldsErrors(fieldNames)

  // Wrapper functions to call onFormChange when form values change
  const handleNameChange = useCallback(
    (newName: string) => {
      setName(newName)
      onFormChange?.()
    },
    [onFormChange],
  )

  const handleDescriptionChange = useCallback(
    (newDescription: string) => {
      setDescription(newDescription)
      onFormChange?.()
    },
    [onFormChange],
  )

  const handleTypeChange = useCallback(
    (newType: KnownType) => {
      setType(newType)
      onFormChange?.()
    },
    [onFormChange],
  )

  const handleCancel = useCallback(() => {
    navigate(`/organizations/${organizationLogin}/settings/issue-fields`)
  }, [navigate, organizationLogin])

  const [showOptionsCommaError, setShowOptionsCommaError] = useState(false)
  const optionsCommaErrorBannerRef = useRef<HTMLElement>(null)

  const handleOptionsChange = useCallback(
    (newOptions: SingleSelectOptionWithId[]) => {
      setOptions(newOptions)
      onFormChange?.()
      // Clear any stale comma-error banner when options change; it will reappear
      // on the next submit attempt if commas are still present.
      setShowOptionsCommaError(false)
    },
    [onFormChange],
  )

  // Validation for select fields requiring at least one option
  const isSelectType = type === KnownTypes.single_select || type === KnownTypes.multi_select
  const isSelectTypeValid = !isSelectType || options.length > 0

  // When the multi-select flag is on and the user has chosen the multi-select type, options
  // serialize to a comma-separated list — so any option name containing a comma must be
  // rejected. Single-select option names can switch to multi-select, so we re-scan at submit
  // time rather than only blocking new entries via SingleSelectForm.
  const optionsWithCommas = useMemo(() => {
    if (!multiSelectEnabled || type !== KnownTypes.multi_select) return []
    return options.filter(option => option.name.includes(','))
  }, [multiSelectEnabled, type, options])

  // Announce success message to screen readers
  useEffect(() => {
    if (successMessage) {
      announce(Resources.saveComplete)
    }
  }, [successMessage])

  // Pin to issues dialog handlers
  const handleOpenPinToIssueTypesDialog = useCallback(() => {
    setIsPinToIssueTypesDialogOpen(true)
  }, [])

  const handleClosePinToIssueTypesDialog = useCallback(() => {
    setIsPinToIssueTypesDialogOpen(false)
  }, [])

  const handleSavePinToIssueTypes = useCallback(
    (selectedIssueTypeIds: string[], newPinnedToNoTypeIssues: boolean) => {
      onPinToIssueTypesChange?.(selectedIssueTypeIds, newPinnedToNoTypeIssues)
      onFormChange?.()
    },
    [onPinToIssueTypesChange, onFormChange],
  )

  const isFieldNotPinned = isCreateNew && allIssueTypes && pinnedIssueTypes?.length === 0 && !pinnedToNoTypeIssues

  const doSubmit = useCallback(async () => {
    setIsSubmitting(true)
    try {
      await onSubmit({
        name,
        description,
        type,
        options,
        visibility: fieldVisibilityPermissions,
      })
    } finally {
      setIsSubmitting(false)
    }
  }, [onSubmit, name, description, type, options, fieldVisibilityPermissions])

  const handleSubmit = useCallback(() => {
    const valid = validate()

    if (!valid || !isSelectTypeValid) {
      setShouldFocusError(true)
      return
    }

    if (optionsWithCommas.length > 0) {
      setShowOptionsCommaError(true)
      // Focus the banner on every failed submit so screen readers re-announce
      // it even when the banner was already visible. Defer to the next frame so
      // the banner is mounted before we focus it. The Banner sets tabIndex={-1}
      // for this purpose.
      requestAnimationFrame(() => optionsCommaErrorBannerRef.current?.focus())
      return
    }

    setShowOptionsCommaError(false)

    if (isFieldNotPinned) {
      setIsNotPinnedConfirmationDialogOpen(true)
      return
    }

    doSubmit()
  }, [
    validate,
    setShouldFocusError,
    isSelectTypeValid,
    optionsWithCommas,
    setShowOptionsCommaError,
    isFieldNotPinned,
    doSubmit,
  ])

  const handleCloseNotPinnedDialog = useCallback(() => {
    setIsNotPinnedConfirmationDialogOpen(false)
  }, [])

  const handleLeaveHidden = useCallback(() => {
    doSubmit()
  }, [doSubmit])

  return (
    <div>
      <div className={styles.titleContainer}>
        <Title showBorder={false}>
          <Link to={`/organizations/${organizationLogin}/settings/issue-fields`}>{Resources.settingsPageHeader}</Link>
          {` / ${pageTitle}`}
        </Title>
      </div>
      <div className={styles.container}>
        {error && (
          <Banner title="Issue field error" variant="critical">
            {error}
          </Banner>
        )}
        {showOptionsCommaError && optionsWithCommas.length > 0 && (
          <Banner ref={optionsCommaErrorBannerRef} title={VALIDATION_MESSAGES.NAME_CONTAINS_COMMA} variant="critical">
            Rename these options before saving: {optionsWithCommas.map(option => option.name).join(' · ')}
          </Banner>
        )}
        <IssueFieldName
          ref={fieldNameRef}
          disabled={isSubmitting}
          name={name}
          error={nameError}
          setName={handleNameChange}
          setError={setNameError}
        />
        <IssueFieldDescription
          ref={fieldDescriptionRef}
          disabled={isSubmitting}
          description={description}
          error={descriptionError}
          setDescription={handleDescriptionChange}
          setError={setDescriptionError}
        />
        <IssueFieldDataType disabled={typeDisabled || isSubmitting} type={type} setType={handleTypeChange} />
        {(type === KnownTypes.single_select || (multiSelectEnabled && type === KnownTypes.multi_select)) && (
          <React.Suspense
            fallback={
              <div className={styles.singleSelectFormContainer}>
                <div
                  style={{
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '8px',
                    paddingTop: '1px',
                    paddingBottom: '1px',
                  }}
                >
                  {options.map(option => (
                    <SkeletonBox key={option.id} height="33px" width="100%" />
                  ))}
                  <SkeletonBox height="64px" width="100%" />
                </div>
              </div>
            }
          >
            <IssueFieldOptions
              disabled={isSubmitting}
              options={options}
              onOptionsChange={handleOptionsChange}
              disallowCommasInName={multiSelectEnabled && type === KnownTypes.multi_select}
            />
          </React.Suspense>
        )}
        <div className={styles.permissionsSection}>
          <div className={styles.permissionsSectionHeader}>
            <span className={styles.permissionsSectionHeading}>{Resources.fieldVisibilityLabel}</span>
          </div>
          <div className={styles.permissionsSectionContent}>
            <IssueFieldVisibilityPermissions
              fieldVisibilityPermissions={fieldVisibilityPermissions}
              onVisibilityPermissionsChange={onVisibilityPermissionsChange}
              disabled={isSubmitting}
            />

            {isPinToIssueTypesEnabled && (
              <>
                <IssueFieldsPinToIssueTypes
                  issueTypes={pinnedIssueTypes}
                  pinnedToNoTypeIssues={pinnedToNoTypeIssues}
                  organizationLogin={organizationLogin}
                  onEditClick={handleOpenPinToIssueTypesDialog}
                  disabled={isSubmitting}
                  editButtonRef={editPinToIssueTypesButtonRef}
                />
                <IssueFieldPinToIssueTypesDialog
                  isOpen={isPinToIssueTypesDialogOpen}
                  allIssueTypes={allIssueTypes}
                  selectedIssueTypeIds={pinnedIssueTypes.map(t => t.id)}
                  pinnedToNoTypeIssues={pinnedToNoTypeIssues}
                  onClose={handleClosePinToIssueTypesDialog}
                  onSave={handleSavePinToIssueTypes}
                  returnFocusRef={editPinToIssueTypesButtonRef}
                  initialPinnedIssueTypeIds={initialPinnedIds}
                  initialPinnedToNoTypeIssues={initialPinnedToNoType}
                />
                <IssueFieldNotPinnedConfirmationDialog
                  isOpen={isNotPinnedConfirmationDialogOpen}
                  onClose={handleCloseNotPinnedDialog}
                  onLeaveHidden={handleLeaveHidden}
                  cancelReturnFocusRef={editPinToIssueTypesButtonRef}
                />
              </>
            )}
          </div>
        </div>

        <IssueFieldActions
          disabled={isSubmitting || !isSelectTypeValid}
          confirmLabel={confirmLabel}
          cancelLabel={cancelLabel}
          onCancel={handleCancel}
          onConfirm={handleSubmit}
          initialData={{
            name: initialData.name ?? '',
            id: initialData.id ?? '',
            organization: initialData.organization ?? '',
          }}
          isCreateNew={isCreateNew}
          successMessage={successMessage}
          showGlobalWarning={hasStartedEditing}
        />
      </div>
    </div>
  )
}
