import {registerDataRouterApp} from '@github-ui/react-core/register-app'

import {issueFieldsSettingsAppBuilder} from './config/app-builder'
import {issueFieldsSettingsEditRoute} from './routes/edit-route'
import {EditPage} from './routes/EditPage'
import {issueFieldsSettingsIndexRoute} from './routes/index-route'
import {IndexPage} from './routes/IndexPage'
import {issueFieldsSettingsNewRoute} from './routes/new-route'
import {NewPage} from './routes/NewPage'

export const issueFieldsSettingsApp = issueFieldsSettingsAppBuilder.createDataRouterAppFromRoutes([
  issueFieldsSettingsIndexRoute.toRoute({Component: IndexPage}),
  issueFieldsSettingsNewRoute.toRoute({Component: NewPage}),
  issueFieldsSettingsEditRoute.toRoute({Component: EditPage}),
])
registerDataRouterApp(issueFieldsSettingsApp)
