import {FormControl, Textarea} from '@primer/react'
import {useCallback} from 'react'

import {ISSUE_FIELD_DESCRIPTION_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import styles from '../routes/NewPage.module.css'

type IssueFieldDescriptionProps = {
  disabled?: boolean
  description: string
  error: string
  setDescription: (description: string) => void
  setError: (error: string) => void
  ref?: React.Ref<HTMLTextAreaElement>
}

export function IssueFieldDescription({
  ref: forwardedRef,
  error,
  setError,
  description,
  setDescription,
  disabled = false,
}: IssueFieldDescriptionProps) {
  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      setError('')
      const value = e.target.value
      setDescription(value)
      if (value.length > ISSUE_FIELD_DESCRIPTION_LIMIT) {
        setError(Resources.descriptionTooLongErrorMessage(ISSUE_FIELD_DESCRIPTION_LIMIT))
      }
    },
    [setError, setDescription],
  )

  return (
    <FormControl disabled={disabled}>
      <FormControl.Label>{Resources.descriptionLabel}</FormControl.Label>
      <Textarea
        value={description}
        onChange={onChange}
        placeholder={Resources.descriptionPlaceholder}
        name="description"
        validationStatus={error ? 'error' : undefined}
        ref={forwardedRef}
        className={styles.textArea}
        resize="none"
        rows={2}
        block
      />
      {error && <FormControl.Validation variant="error">{error}</FormControl.Validation>}
    </FormControl>
  )
}
